def _project_module_recovery_metadata(
    project_result: Any,
    *,
    module: str | None,
    module_path: str | None,
) -> tuple[str | None, list[dict[str, str]]]:
    """Return bounded module-recovery metadata already discovered by Project Docs."""

    project_docs = getattr(project_result, "project_docs", None)
    reason = str(getattr(project_docs, "reason_code", None) or "").strip()
    if not reason and str(getattr(project_result, "status", "")) in _MODULE_RECOVERY_REASON_CODES:
        reason = str(project_result.status)
    if reason not in _MODULE_RECOVERY_REASON_CODES:
        return None, []

    candidates: list[dict[str, str]] = []
    seen: set[str] = set()
    requested_name = str(module or "").strip()
    for source in getattr(project_docs, "candidate_sources", ()) or ():
        if not isinstance(source, dict):
            continue
        candidate_path = str(source.get("module_path") or "").strip()
        if not candidate_path or candidate_path in seen:
            continue
        if reason == "module_ambiguous" and requested_name and not module_path:
            if requested_name not in {
                str(source.get("module_name") or "").strip(),
                str(source.get("module_id") or "").strip(),
            }:
                continue
        seen.add(candidate_path)
        candidate = {"module_path": candidate_path}
        for key in ("module_name", "module_type"):
            value = str(source.get(key) or "").strip()
            if value:
                candidate[key] = value
        candidates.append(candidate)
        if len(candidates) >= 8:
            break
    return reason, candidates

def _collect_pending_actions(lane_results: list[Any]) -> dict[str, Any]:
        pending: dict[str, Any] = {"requires_confirmation": False, "next_actions": []}
        merged_patch: dict[str, Any] = {}
        patch_conflict = False
        for result in lane_results:
            if not getattr(result, "requires_confirmation", False):
                continue
            pending["requires_confirmation"] = True
            if not pending.get("confirmation_reason"):
                pending["confirmation_reason"] = getattr(result, "confirmation_reason", None)
            next_action = getattr(result, "next_action", None) or None
            patch = getattr(result, "arguments_patch", None) or None
            if next_action:
                pending["next_actions"].append(next_action)
                pending.setdefault("next_action", next_action)
            if patch:
                action = next_action or {"type": "get_docs_context", "tool": "get_docs_context", "arguments_patch": patch}
                if action not in pending["next_actions"]:
                    pending["next_actions"].append(action)
                for key, value in patch.items():
                    if key in merged_patch and merged_patch[key] != value:
                        patch_conflict = True
                    else:
                        merged_patch[key] = value
        if merged_patch and not patch_conflict:
            pending["arguments_patch"] = merged_patch
        return pending

