def status_for(self, record: LibraryRecord, size_bytes: int | None = None) -> str:
        if record.status == "failed":
            return "failed"
        if record.status == "partial" or str(record.last_error or "").startswith("partial ingestion:"):
            return "partial"
        pages, chunks = self.count_index_entries(record)
        if pages == 0 and chunks == 0 and Path(self.deps._index_config_for(record).index.db_path).exists():
            return "empty_index"
        size = self.index_size_for(record) if size_bytes is None else size_bytes
        if size == 0:
            return "empty_index"
        if self.deps._is_stale(record.last_refreshed_at):
            return "stale"
        manifest = (record.target_spec or {}).get("source_manifest") or {}
        policy_version = (record.target_spec or {}).get("ingestion_policy_version")
        if (
            manifest.get("schema_version") == 2
            and policy_version is not None
            and policy_version != MANIFEST_INGESTION_POLICY_VERSION
        ):
            return "needs_refresh"
        return "indexed"

def _python_candidates(payload: Any, library: str, version: str | None) -> list[dict[str, Any]]:
    info = payload.get("info") if isinstance(payload, dict) else None
    if not isinstance(info, dict):
        return []
    project_urls = info.get("project_urls") if isinstance(info.get("project_urls"), dict) else {}
    ranked: list[tuple[int, str, str]] = []
    for label, raw_url in project_urls.items():
        if not isinstance(raw_url, str) or not _safe_public_url(raw_url):
            continue
        normalized_label = str(label).casefold()
        rank = 0 if any(term in normalized_label for term in ("documentation", "docs", "reference")) else 2
        if any(term in normalized_label for term in ("homepage", "home")):
            rank = 1
        ranked.append((rank, str(label), raw_url))
    home_page = info.get("home_page")
    if isinstance(home_page, str) and _safe_public_url(home_page):
        ranked.append((1, "Project homepage", home_page))
    return _dedupe_candidates([
        _candidate(
            url,
            label=label,
            confidence="high" if rank == 0 else "medium",
            source="pypi_project_metadata",
            ecosystem="python",
            version=version,
            source_type="web",
            library=library,
        )
        for rank, label, url in sorted(ranked)
    ])

